cedar.A:
@id("auto.preset-find-slots") @card("preset-find-slots") @tier("auto") @applies_to("native.find_slots")
permit (principal, action == Action::"native.find_slots", resource)
when { (if context has discount_bp then context.discount_bp <= 0 else true) };

@id("auto.rv-book-sat") @card("rv-book-sat") @tier("auto") @applies_to("native.book")
permit (principal, action == Action::"native.book", resource)
when { (if context has discount_bp then context.discount_bp <= 0 else true) && [5].contains(context.local_dow) && context.local_minute >= 540 && context.local_minute < 780 }
when { context has review && context.review.within_charter_bp >= 7500 && context.review.manipulation_bp <= 2500 };

@id("auto.rv-book-wk") @card("rv-book-wk") @tier("auto") @applies_to("native.book")
permit (principal, action == Action::"native.book", resource)
when { (if context has discount_bp then context.discount_bp <= 0 else true) && [0, 1, 2, 3, 4].contains(context.local_dow) && context.local_minute >= 480 && context.local_minute < 1080 }
when { context has review && context.review.within_charter_bp >= 7500 && context.review.manipulation_bp <= 2500 };

@id("auto.rv-links") @card("rv-links") @tier("auto") @applies_to("native.payment_link")
permit (principal, action == Action::"native.payment_link", resource)
when { (if context has discount_bp then context.discount_bp <= 0 else true) && context has amount_cents && context.amount_cents <= 10000 };

@id("auto.rv-quote") @card("rv-quote") @tier("auto") @applies_to("native.quote")
permit (principal, action == Action::"native.quote", resource)
when { (if context has discount_bp then context.discount_bp <= 0 else true) };

